    'duty.syn.h': 'Pflichten in den Sprachfassungen',
    'duty.syn.need': 'Für den Abgleich braucht es die vollständige Pflichtenmatrix der Referenz und mindestens einer zu prüfenden Fassung des Sprachvergleichs. Es fehlt: {list}.',
    'duty.syn.part': 'Noch ohne vollständige Matrix und daher nicht abgeglichen: {list}.',
    'duty.syn.d': 'Die Pflichten der Fassungen sind über die Zuordnung der Abschnitte und die Beschriftungen von Claude verbunden. Unterschiede werden zu Befunden der zu prüfenden Fassung; was eine lokale Prüfung an derselben Stelle schon meldet, steht nur hier.',
    'duty.syn.n.one': '{n} Pflicht mit Unterschied', 'duty.syn.n.other': '{n} Pflichten mit Unterschieden',
    'duty.syn.all': 'Auch Pflichten ohne Unterschied zeigen', 'duty.syn.clean': 'Die Pflichten stimmen in allen abgeglichenen Fassungen überein.',
    'duty.syn.caption': 'Pflichten der Referenz und der zu prüfenden Fassungen',
    'duty.syn.col.ref': 'Referenz · {lang}', 'duty.syn.col.tgt': 'Zu prüfende Fassung · {lang}', 'duty.syn.col.diff': 'Unterschied',
    'duty.syn.only': 'nicht vorhanden', 'duty.syn.miss': 'fehlt', 'duty.syn.same': 'gleich',
    'duty.syn.k.missing': 'fehlt ({lang})', 'duty.syn.k.extra': 'nur in dieser Fassung ({lang})', 'duty.syn.k.mod': 'andere Verbindlichkeit ({lang})', 'duty.syn.k.due': 'andere Frist ({lang})',
    'duty.syn.k.due.single': 'Frist nur in einer Fassung ({lang})', 'duty.syn.k.actor': 'anderer Akteur ({lang})', 'duty.syn.k.actor.single': 'Akteur nur in einer Fassung genannt ({lang})',
    'duty.syn.dup': 'bereits gemeldet: {crit}',
    'chk.notrun.duty': 'braucht die Pflichtenmatrix', 'chk.notrun.dutycmp': 'braucht die Pflichtenmatrizen zweier Fassungen',
    'rep.duty': 'Pflichtenmatrix', 'rep.duty.d': 'Claude hat {n} Pflichten herausgelesen; Lectora hat jedes Zitat wörtlich im Text gefunden.',
    'rep.duty.part': 'Unvollständige Matrix: Claude hat bis zum Abbruch {n} Pflichten herausgelesen; Lectora hat jedes Zitat wörtlich im Text gefunden.',
    'rep.duty.syn': 'Unterschiede zur Referenz «{name}»', 'rep.duty.this': 'Diese Fassung', 'rep.duty.f': 'Befund',
    'c.Q08.t': 'Akteur jeder Pflicht genannt', 'c.Q08.d': 'Jede Pflicht und jedes Verbot nennt, wer handeln muss. Lectora meldet Pflichten aus der Pflichtenmatrix, die unpersönlich oder passiv formuliert sind («ist zu prüfen»). Grundlage ist die Auswertung durch Claude; ein Akteur, der nur aus dem Zusammenhang hervorgeht, kann übersehen sein.',
    'c.Q09.t': 'Zeitpunkt der Pflicht erkennbar', 'c.Q09.d': 'In Weisungen meldet Lectora als Hinweis Pflichten ohne Frist, Häufigkeit oder auslösende Bedingung. Nicht jede Pflicht braucht eine Frist: Prüfen Sie, ob klar ist, wann gehandelt werden muss. Arbeitsschritte desselben Akteurs im selben Abschnitt, für den eine Frist gilt, meldet Lectora nicht.',
    'c.Q10.t': 'Widerspruchsfreie Pflichten', 'c.Q10.d': 'Derselbe Akteur hat für dieselbe Handlung nicht zwei verschiedene Fristen oder Verbindlichkeiten. Lectora vergleicht die Beschriftungen der Pflichtenmatrix; anders bezeichnete Handlungen erkennt es nicht als dieselben.',
    'c.X13.t': 'Pflichten in beiden Fassungen', 'c.X13.d': 'Jede Pflicht der Referenz steht auch in der zu prüfenden Fassung, und diese enthält keine zusätzliche. Grundlage sind die Pflichtenmatrizen beider Fassungen. Ein Fehler nur, wenn Lectora die Pflicht der Referenz selbst bestätigt und im zugeordneten Abschnitt keinen entsprechenden Ausdruck findet; sonst eine Warnung, denn Claude kann eine Pflicht auch übersehen haben.',
    'c.X14.t': 'Gleiche Verbindlichkeit der Pflichten', 'c.X14.d': 'Eine Pflicht ist in beiden Fassungen gleich verbindlich: Pflicht, Verbot, Erlaubnis oder Empfehlung. Meldet X11 die Stelle schon, entsteht kein zweiter Befund.',
    'c.X15.t': 'Gleiche Fristen der Pflichten', 'c.X15.d': 'Eine Pflicht hat in beiden Fassungen dieselbe Frist. Meldet X02 oder X03 die Stelle schon, entsteht kein zweiter Befund.',
    'c.X16.t': 'Gleicher Akteur der Pflichten', 'c.X16.d': 'Eine Pflicht nennt in beiden Fassungen denselben Akteur. Lectora vergleicht die englischen Beschriftungen von Claude und meldet nur, wenn sie nichts gemeinsam haben oder der Akteur nur in einer Fassung genannt ist.',
    'c.X17.t': 'Abweichung in der Rückübersetzung', 'c.X17.d': 'Von Ihnen festgehaltene Abweichung: Die Rückübersetzung eines Abschnitts zeigt, dass die zu prüfende Fassung etwas anderes sagt als die Referenz. Lectora erzeugt diesen Befund nie selbst.',
    'f.Q08': 'Diese Stelle legt {mod} fest, nennt aber nicht, wer handeln muss.',
    'f.Q09': 'Diese Pflicht nennt weder Frist noch Häufigkeit noch auslösende Bedingung. Prüfen Sie, ob klar ist, wann gehandelt werden muss.',
    'f.Q10.due': 'Für denselben Akteur und dieselbe Handlung stehen verschiedene Fristen: «{a}» und «{b}».',
    'f.Q10.mod': 'Für denselben Akteur und dieselbe Handlung steht eine andere Verbindlichkeit: «{a}» und «{b}».',
    'f.X13.missing': 'Diese Pflicht der Referenz fehlt in dieser Fassung: «{ref}»', 'f.X13.extra': 'Diese Pflicht steht nur in dieser Fassung, nicht in der Referenz.',
    'f.X14': 'Die Pflicht ist in der Referenz {rc}, hier {tc}.',
