    'chk.bulk.shown.none': 'Rifiuta le proposte mostrate',
    'tip.bulk.shown': 'Vale solo per le proposte in sospeso mostrate dal filtro e si può annullare.',
    'rep.withacc': 'tenendo conto delle correzioni accettate',
    'rep.acc': 'Proposte accettate',
